2	 * A seeded 32-bit generator (mulberry32). Its whole state is one unsigned integer kept in the match state, so a
3	 * snapshot restores the random sequence exactly.
4	 */
5	export function nextRandom(state: number): { value: number; state: number } {
6	  const next = (state + 0x6d2b79f5) >>> 0;
7	  let t = next;
8	  t = Math.imul(t ^ (t >>> 15), t | 1);
9	  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
10	  return { value: (t ^ (t >>> 14)) >>> 0, state: next };
11	}
