14	export function nextInt(state: number, bound: number): { value: number; state: number } {
15	  if (!Number.isInteger(bound) || bound <= 0) throw new RangeError(`bound must be a positive integer, got ${bound}`);
16	  const drawn = nextRandom(state);
17	  return { value: drawn.value % bound, state: drawn.state };
18	}
