1	/**
2	 * The sea is a bounded rectangle of tiles laid out like screen coordinates: origin (0,0) at the top-left, x grows
3	 * right and y grows down. Every tile is split into a fixed integer number of sub-units, and all positions and speeds
4	 * in the simulation are integer sub-units.
5	 */
6	export const SUB_UNITS_PER_TILE = 256;
7	
8	/** What a tile is. Sea and docks are navigable; land and shoals stop ships. */
9	export const Terrain = {
10	  Sea: 0,
11	  Land: 1,
12	  Shoal: 2,
